{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescuer arrives at the ruined city.",
      "visual_description": "A vast ruined city sprawls under a grey sky, broken towers and collapsed walls lined with faded royal banners flapping in the wind. The glass diver stands at the edge of the rubble, helmet gleaming.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the Cartographer studies the city map.",
      "visual_description": "Mara unrolls an ancient map across a fallen stone block, compass in hand, tracing a route through the ruins while the glass diver looks over her shoulder.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp warns of a cursed tower.",
      "visual_description": "Inside a collapsed archway, the Oracle Lamp flickers with a single glowing eye in its flame, casting long shadows as it speaks of a tower that traps all who enter.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scouts ahead through broken streets.",
      "visual_description": "The tin fox scurries over rubble, its key-wind tail twitching, blue glass eyes scanning the path between collapsed columns and torn banners.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The sleeping tax collector blocks the way.",
      "visual_description": "A doorway is blocked by the sleeping tax collector, who snores on a pile of stamped papers, ledger book under his head, oblivious to the urgency.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "Mara convinces the tax collector to move.",
      "visual_description": "Mara kneels beside the sleeping tax collector, shaking his shoulder while the Oracle Lamp hovers nearby, casting a bright light on his face.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The glass diver dives through a reflective puddle.",
      "visual_description": "The glass diver plunges into a shimmering puddle of rainwater, disappearing into its surface as if swimming through a mirror, ripples spreading outward.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The tin fox reports armored patrols near the square.",
      "visual_description": "The tin fox peeks around a corner, its blue eyes reflecting the gleam of metal as a patrol of faceless armor clanks past, their movements stiff and mechanical.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Mara leads the group through a hidden alley.",
      "visual_description": "Mara gestures urgently, leading the glass diver, the Oracle Lamp, and the tin fox down a narrow alley lined with faded royal shields and torn banners.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The Oracle Lamp reveals a magic door.",
      "visual_description": "In a deserted courtyard, the Oracle Lamp's flame brightens as it illuminates a door covered in glowing runes, pulsing with a soft blue light.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The glass diver unlocks the magic door.",
      "visual_description": "The glass diver presses a hand to the door's surface, and patterns of light ripple across the runes as the door slowly swings open, revealing a dark passage.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The sleeping tax collector stumbles into the passage.",
      "visual_description": "The sleeping tax collector, still half-asleep, wanders into the passage after the group, clutching his ledger book and trailing stamped papers.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Armored patrols surround the far end of the passage.",
      "visual_description": "At the end of the passage, armored patrols line the exit, their faceless helmets turning in unison as the group emerges.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 14,
      "caption": "The glass diver uses a broken window to distract the patrols.",
      "visual_description": "The glass diver dives through a cracked window pane, emerging on the other side to shatter a pile of debris, drawing the patrols' attention away.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "Mara finds a route to the escape bridge.",
      "visual_description": "Mara spreads her map on a fallen column, tracing a path with her finger while the Oracle Lamp lights the map, the tin fox watching intently.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The group races toward the bridge.",
      "visual_description": "The group runs across a wide plaza strewn with rubble, the bridge visible ahead, its stone arches spanning a chasm, as armored patrols close in from behind.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The tin fox holds the bridge entrance.",
      "visual_description": "The tin fox stands at the bridge entrance, its small frame braced, blue eyes glowing as it uses its tail to trigger a mechanism that drops a portcullis behind the group.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "The glass diver escapes across the bridge.",
      "visual_description": "The glass diver leads the group across the stone bridge, the ruined city behind them fading into mist, the Oracle Lamp glowing warmly ahead, as the tin fox follows with a weary key-wind.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

